const input = $input.first()?.json?.body || {};
const experiments = input.experiments || [];
const now = new Date();

const activeExperiments = experiments.length > 0 ? experiments : [
  {
    id: 'EXP-001',
    hypothesis: 'Security-conscious founders respond to compliance-risk framing',
    fit_tested: 'MP',
    start_date: new Date(now - 14 * 24 * 60 * 60 * 1000).toISOString(),
    end_date: new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString(),
    stop_conditions: [
      { metric: 'response_rate', threshold: 0.15, operator: 'gte', description: 'Response rate >= 15% confirms hypothesis' },
      { metric: 'response_rate', threshold: 0.05, operator: 'lte', description: 'Response rate <= 5% falsifies hypothesis' }
    ],
    current_metrics: { response_rate: 0.08, sample_size: 25 },
    status: 'running',
    variant: 'compliance-risk-email-v1'
  },
  {
    id: 'EXP-002',
    hypothesis: 'LinkedIn DM outperforms cold email for builder segment',
    fit_tested: 'PC',
    start_date: new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString(),
    end_date: new Date(now.getTime() + 21 * 24 * 60 * 60 * 1000).toISOString(),
    stop_conditions: [
      { metric: 'response_rate', threshold: 0.20, operator: 'gte', description: 'LinkedIn wins — confirm channel' },
      { metric: 'sample_size', threshold: 50, operator: 'gte', description: 'Sufficient sample reached' }
    ],
    current_metrics: { response_rate: 0.12, sample_size: 18 },
    status: 'running',
    variant: 'linkedin-dm-builder'
  }
];

const enriched = activeExperiments.map(exp => ({
  ...exp,
  days_running: Math.floor((now - new Date(exp.start_date)) / (24 * 60 * 60 * 1000)),
  days_remaining: Math.max(0, Math.floor((new Date(exp.end_date) - now) / (24 * 60 * 60 * 1000))),
  progress_pct: Math.min(100, Math.floor((now - new Date(exp.start_date)) / (new Date(exp.end_date) - new Date(exp.start_date)) * 100))
}));

return [{ json: { active_experiments: enriched, checked_at: now.toISOString() } }];

const input = $input.first().json;
const experiments = input.active_experiments || [];

const evaluate = (exp) => {
  const triggered = [];
  for (const cond of (exp.stop_conditions || [])) {
    const val = exp.current_metrics?.[cond.metric];
    if (val === undefined) continue;
    let met = false;
    if (cond.operator === 'gte') met = val >= cond.threshold;
    else if (cond.operator === 'lte') met = val <= cond.threshold;
    else if (cond.operator === 'gt') met = val > cond.threshold;
    else if (cond.operator === 'lt') met = val < cond.threshold;
    if (met) triggered.push(cond);
  }

  const isOverdue = exp.days_remaining <= 0;
  const confirmed = triggered.some(t => t.description?.includes('confirms') || t.description?.includes('wins'));
  const falsified = triggered.some(t => t.description?.includes('falsifies'));

  let recommendation = 'continue';
  let conclusion = null;
  if (confirmed) { recommendation = 'conclude_positive'; conclusion = 'CONFIRMED: Hypothesis supported'; }
  else if (falsified) { recommendation = 'conclude_negative'; conclusion = 'FALSIFIED: Pivot or abandon'; }
  else if (isOverdue) { recommendation = 'conclude_inconclusive'; conclusion = 'INCONCLUSIVE: Time expired'; }

  return { ...exp, triggered_conditions: triggered, recommendation, conclusion, should_stop: recommendation !== 'continue' };
};

const evaluated = experiments.map(evaluate);
return [{ json: { evaluated_experiments: evaluated, stopping_count: evaluated.filter(e => e.should_stop).length, continuing_count: evaluated.filter(e => !e.should_stop).length } }];

const input = $input.first().json;
const experiments = input.evaluated_experiments || [];
const emojiMap = { continue: '🔬', conclude_positive: '✅', conclude_negative: '❌', conclude_inconclusive: '❓' };

const lines = experiments.map(exp => {
  const emoji = emojiMap[exp.recommendation] || '🔬';
  const metrics = Object.entries(exp.current_metrics || {}).map(([k,v]) => k + ': ' + (typeof v === 'number' && v < 1 ? Math.round(v*100)+'%' : v)).join(', ');
  return emoji + ' *' + exp.id + '* — ' + exp.hypothesis + '\n  Fit: ' + exp.fit_tested + ' | Day ' + exp.days_running + ' (' + exp.progress_pct + '%)\n  ' + metrics + '\n  ' + (exp.conclusion || 'Continuing — ' + exp.days_remaining + 'd remaining');
});

const slackMsg = [
  '🧪 *Four-Fit Experiment Tracker — Week of ' + new Date().toLocaleDateString() + '*',
  '',
  '*Active: ' + experiments.length + ' | Action Required: ' + input.stopping_count + ' | Continuing: ' + input.continuing_count + '*',
  '',
  ...lines,
  '',
  input.stopping_count > 0 ? '⚠️ *' + input.stopping_count + ' experiment(s) need conclusion decision*' : '✅ All experiments running normally'
].join('\n');

return [{ json: { slack_message: slackMsg, generated_at: new Date().toISOString(), summary: { total: experiments.length, stopping: input.stopping_count, continuing: input.continuing_count } } }];

